import * as cheerio from "cheerio";
import type { FeedConfig, FeedItem, ScraperHelpers } from "@rss-agentic/core";

export async function fetchFeed(
  config: FeedConfig,
  helpers: ScraperHelpers,
): Promise<FeedItem[]> {
  // 1. Fetch the listing page (Webflow SSR — plain fetch works)
  const listHtml = await fetch(config.url).then((r) => r.text());
  const $list = cheerio.load(listHtml);

  // 2. Parse each card on the listing page
  const listingItems: {
    id: string;
    title: string;
    url: string;
    publishedAt: string;
  }[] = [];

  $list(".card_blog_list_wrap").each((_i, el) => {
    const title = $list(el).find(".card_blog_list_title").text().trim();
    const linkEl = $list(el)
      .find('a.clickable_link[href*="/blog/"]')
      .first();
    const href = linkEl.attr("href");
    const dateStr = $list(el)
      .find('[fs-list-fieldtype="date"]')
      .text()
      .trim();

    if (title && href) {
      const fullUrl = href.startsWith("http")
        ? href
        : `https://claude.com${href}`;
      const publishedAt = dateStr
        ? new Date(dateStr).toISOString()
        : new Date().toISOString();
      // Use the URL path as a stable ID
      const path = new URL(fullUrl).pathname.replace(/\/$/, "");
      const id = path.split("/").pop() || path;

      listingItems.push({ id, title, url: fullUrl, publishedAt });
    }
  });

  // 3. Fetch each detail page concurrently to extract image + full body
  const results = await Promise.all(
    listingItems.map(async (item) => {
      try {
        const detailHtml = await fetch(item.url).then((r) => r.text());
        const $detail = cheerio.load(detailHtml);

        // imageUrl: first <meta property="og:image"> (skip the generic fallback)
        const ogImage = $detail('meta[property="og:image"]')
          .first()
          .attr("content");

        // contentHtml: full inner HTML of .u-rich-text-blog (first instance = main body)
        const contentEl = $detail(".u-rich-text-blog").first();
        const contentHtml =
          contentEl.length > 0 ? contentEl.html()! : undefined;

        const feedItem: FeedItem = {
          id: item.id,
          title: item.title,
          url: item.url,
          publishedAt: item.publishedAt,
          source: config.slug,
        };

        if (ogImage) {
          feedItem.imageUrl = ogImage.startsWith("http")
            ? ogImage
            : new URL(ogImage, item.url).href;
        }
        if (contentHtml) {
          feedItem.contentHtml = contentHtml;
        }

        return feedItem;
      } catch (err) {
        // Graceful degradation: return item without detail fields
        console.error(`Failed to fetch detail page ${item.url}:`, err);
        const fallback: FeedItem = {
          id: item.id,
          title: item.title,
          url: item.url,
          publishedAt: item.publishedAt,
          source: config.slug,
        };
        return fallback;
      }
    }),
  );

  return results;
}
